// /app/jackpot-bubble-demo.js — local demo for the replay-panel bubble pop SFX.
//
// Mounts a fresh <replay-panel> via its tutorial-fixture hook (setTutorialFixture,
// gated on document.documentElement[data-degenerus-tutorial]) so the jackpot
// board can be spun and popped with no wallet/network required. Each scenario
// below is a hand-built fixture engineered to land a specific outcome under
// every quadrant bubble; see the #revealQuadrant/#revealCenter tier rules in
// components/replay-panel.js for exactly how outcome -> tier is derived.
//
// FLIP wins and the center bonus bubble only exist on the bonus round (Roll 2),
// which setTutorialFixture always makes reachable: #filterPlayerWins sees a
// resolved (if empty) dayRoll2 for the selected day and #dayBonusTraitDraw
// defaults true, so #hasBonus ends up true regardless of fixture content. The
// bonus round currency is always FLIP (jackpot-buckets.js buildRoll2BucketSummaries),
// and Roll 1 (the main jackpot) can only ever be ETH through this hook — there is
// no public way to flip #openingFlipDay from a fixture — so a FLIP win can only be
// demonstrated on the bonus board.
import './components/replay-panel.js';
import { isMuted, setMuted, warmup } from './app/jackpot-sfx.js';

const PLAYER = '0x0000000000000000000000000000000000000001';
const OTHER_A = '0x0000000000000000000000000000000000000002';

// One trait id per quadrant; quadrant N owns the range [64N, 64N + 63].
const MAIN_TRAITS = [10, 70, 140, 200];
const BONUS_TRAITS = [20, 80, 150, 210];

const ETH_SOLO_AMOUNT = '100000000000';   // sole winner of the trait -> gold tier 3
const ETH_SPLIT_A = '60000000000';        // two winners of the same trait -> tier 3, no gold
const ETH_SPLIT_B = '40000000000';
const FLIP_AMOUNT = '5000000000000000000';     // 5 FLIP, bonus-round quadrant win -> tier 2
const CENTER_AMOUNT = '8000000000000000000';   // 8 FLIP, center bonus bubble -> tier 2

function win(winner, traitId, amount, awardType) {
  return { winner, traitId, amount, awardType };
}

function fixture(overrides) {
  return {
    day: 42, level: 3, purchaseLevel: 3, player: PLAYER,
    dayInPhase: 5, entryCount: 8,
    mainTraits: [...MAIN_TRAITS], bonusTraits: [...BONUS_TRAITS],
    playerTraits: [], futureTraits: [],
    roll1Wins: [], roll2Wins: [],
    ...overrides,
  };
}

// Each scenario engineers the outcome under every quadrant bubble by
// controlling ownership (does the player hold the drawn badge?) and the win
// rows behind it (does anyone/only the player win that badge?):
//   - not owned, no win               -> guaranteed-loss cover, dull miss (tier 0)
//   - owned, nobody wins              -> blue/gold cover that pops pink (tier 1)
//   - the player wins, 2+ winning rows on the trait -> ETH/FLIP win (tier 3 / tier 2)
//   - the player wins, exactly 1 winning row (ETH)  -> solo ETH win, gold (tier 3 gold)
const SCENARIOS = {
  misses: {
    label: 'All misses',
    describe: 'Every quadrant is an unowned, guaranteed loss. Spin, then pop for the dull miss.',
    build: () => fixture({}),
  },
  'near-misses': {
    label: 'Near misses',
    describe: 'The player owns every drawn badge, but nobody wins. Blue/gold covers pop pink.',
    build: () => fixture({
      playerTraits: [...MAIN_TRAITS],
      futureTraits: [...BONUS_TRAITS],
    }),
  },
  'flip-wins': {
    label: 'FLIP wins',
    describe: 'Main jackpot is a clean miss. Roll 1 can never pay FLIP through this fixture, '
      + 'so spin, pop the misses, then tap BONUS SPIN for four FLIP wins.',
    build: () => fixture({
      futureTraits: [...BONUS_TRAITS],
      roll2Wins: BONUS_TRAITS.map((traitId) => win(PLAYER, traitId, FLIP_AMOUNT, 'flip')),
    }),
  },
  'eth-win': {
    label: 'ETH win',
    describe: 'Every quadrant trait has two ETH winners (the player + another wallet) — a win, not solo.',
    build: () => fixture({
      playerTraits: [...MAIN_TRAITS],
      roll1Wins: MAIN_TRAITS.flatMap((traitId) => [
        win(PLAYER, traitId, ETH_SPLIT_A, 'eth'),
        win(OTHER_A, traitId, ETH_SPLIT_B, 'eth'),
      ]),
    }),
  },
  'solo-eth-win': {
    label: 'Solo ETH win (gold)',
    describe: 'Every quadrant trait has exactly one winning row — the player, alone. Gold pop.',
    build: () => fixture({
      playerTraits: [...MAIN_TRAITS],
      roll1Wins: MAIN_TRAITS.map((traitId) => win(PLAYER, traitId, ETH_SOLO_AMOUNT, 'eth')),
    }),
  },
  mixed: {
    label: 'Mixed (one of each)',
    describe: 'Main board: a miss, a near miss, an ETH win, and a solo ETH win. '
      + 'Bonus round (tap BONUS SPIN): a FLIP win and the center bonus bubble.',
    build: () => fixture({
      playerTraits: [MAIN_TRAITS[1], MAIN_TRAITS[3]],
      futureTraits: [BONUS_TRAITS[0]],
      roll1Wins: [
        win(PLAYER, MAIN_TRAITS[2], ETH_SPLIT_A, 'eth'),
        win(OTHER_A, MAIN_TRAITS[2], ETH_SPLIT_B, 'eth'),
        win(PLAYER, MAIN_TRAITS[3], ETH_SOLO_AMOUNT, 'eth'),
      ],
      roll2Wins: [
        win(PLAYER, BONUS_TRAITS[0], FLIP_AMOUNT, 'flip'),
        win(PLAYER, null, CENTER_AMOUNT, 'farFutureCoin'),
      ],
    }),
  },
};

const mount = document.getElementById('replay-mount');
const select = document.getElementById('scenario-select');
const describeEl = document.getElementById('scenario-describe');
const chimeToggle = document.getElementById('chime-toggle');
const mute = document.getElementById('pop-demo-mute');
mute.checked = isMuted();
mute.addEventListener('change', () => setMuted(mute.checked));

let panel = null;

function loadScenario(key) {
  const scenario = SCENARIOS[key] || SCENARIOS.misses;
  describeEl.textContent = scenario.describe;
  warmup();
  panel?.remove();
  panel = document.createElement('replay-panel');
  mount.appendChild(panel);
  panel.revealChimes = chimeToggle.value !== 'off';
  panel.setTutorialFixture(scenario.build());
}

select.addEventListener('change', () => loadScenario(select.value));
chimeToggle.addEventListener('change', () => {
  if (panel) panel.revealChimes = chimeToggle.value !== 'off';
});

loadScenario(select.value);
